type ClaimInput = { slug: string; statement: string; sources: string[]; category: EvidenceClaim["evidenceCategory"]; limitation: string; population?: string };
const claimInputs: ClaimInput[] = [
  { slug: "nodal-deposit-size", statement: "A breast-cancer axillary nodal deposit larger than 0.2 mm and no larger than 2 mm is micrometastatic; a deposit larger than 2 mm exceeds that category.", sources: ["nci-tnm-2025"], category: "definition", limitation: "Single government source for this exact size definition; size category is not itself a universal ALND rule. Constructed measurements are not new clinical thresholds." },
  { slug: "dcis-margin", statement: "For pure DCIS treated with breast conservation and whole-breast radiation, a negative margin of at least 2 mm is adequate without routine widening.", sources: ["asbrs-margins-2024", "ontario-dcis-2024"], category: "management", limitation: "Do not extend this to omission of radiation or an automatic operation for every narrower negative margin." },
  { slug: "radial-positive-margin", statement: "Tumor at a final radial inked boundary after lumpectomy generally warrants further excision when residual breast tissue remains.", sources: ["asbrs-margins-2024", "ontario-dcis-2024"], category: "management", limitation: "A true anterior/posterior anatomic boundary without remaining breast tissue and individualized competing risks require separate assessment." },
  { slug: "specimen-provenance", statement: "An oriented additional cavity specimen can establish a new final external boundary; the original specimen distance must be reconciled with that boundary.", sources: ["asbrs-margins-2024"], category: "evaluation", limitation: "Single adequate source; the exact constructed orientation is explicit. A loosely labelled fragment cannot silently replace a final margin." },
  { slug: "invasive-margin", statement: "In US breast-conserving treatment of invasive carcinoma with an associated DCIS component, absence of tumor on ink generally satisfies the margin standard.", sources: ["asbrs-margins-2024", "nci-treatment-2025"], category: "management", limitation: "Not the pure-DCIS or DCIS-microinvasion rule; residual suspicious imaging and extensive close disease still need clinical assessment." },
  { slug: "dcis-axilla", statement: "Conventional DCIS management usually omits sentinel surgery for uncomplicated lumpectomy and includes it with mastectomy because subsequent mapping may fail.", sources: ["asbrs-axilla-2026"], category: "management", limitation: "Single current source; planned delayed SPIO mapping and specific invasion/mapping concerns are exceptions, not universal rules." },
  { slug: "upfront-limited-nodes", statement: "After upfront breast conservation, selected clinically node-negative invasive cancers with one or two positive sentinel nodes and planned whole-breast radiation can avoid completion dissection.", sources: ["asbrs-axilla-2026", "nci-treatment-2025"], category: "management", limitation: "The case supplies small primary, no gross extranodal disease and systemic treatment. This does not extend Z0011 to post-NST residual disease or heavier nodal burden." },
  { slug: "mastectomy-rni", statement: "For selected upfront mastectomy patients with one or two positive sentinel nodes, regional nodal irradiation can support omission of completion dissection.", sources: ["asbrs-axilla-2026"], category: "management", limitation: "Single adequate 2026 society source; radiation commitment and trial-population applicability matter. Omission is not an unconditional mastectomy rule." },
  { slug: "nst-negative-staging", statement: "After NST in initially node-positive, now clinically node-negative noninflammatory cancer, targeted removal of the clipped node with optimized sentinel mapping improves staging reliability.", sources: ["asbrs-axilla-2026"], category: "management", limitation: "Single current source. Dual mapping and retrieval of more than two sentinel nodes reduce false negatives; a negative ultrasound cannot establish ypN0." },
  { slug: "nst-residual-nodes", statement: "Residual sentinel-node micro- or macrometastasis after NST remains an indication for completion axillary dissection in current ASBrS guidance.", sources: ["asbrs-axilla-2026"], category: "management", limitation: "Single current source; not isolated tumor cells. Mature randomized replacement-by-radiation evidence was not established by the retrieved guide." },
  { slug: "nst-initial-cno", statement: "A clinically node-negative axilla after NST still ordinarily undergoes sentinel staging, even with a radiographic breast response.", sources: ["asbrs-axilla-2026"], category: "management", limitation: "Single current source; investigational omission populations are not automatically standard care." },
  { slug: "high-burden-axilla", statement: "Pretreatment clinically bulky or fixed biopsy-proven axillary disease and inflammatory disease do not acquire the usual cN1 de-escalation pathway solely through response.", sources: ["asbrs-axilla-2026"], category: "safety_boundary", limitation: "Single current society source; sparse cN2-3 sentinel data. Exact pretreatment examination must be retained." },
  { slug: "her2-sequence", statement: "For a substantial HER2-positive, node-positive nonmetastatic primary, neoadjuvant chemotherapy with HER2-directed therapy is an established treatment approach.", sources: ["asbrs-bcs-2026", "nci-treatment-2025"], category: "management", limitation: "No universal regimen, dose, interval or complete medical eligibility rule is authored. This is not a recommendation for every small HER2-positive tumor." },
  { slug: "residual-her2", statement: "Residual invasive HER2-positive cancer after taxane/trastuzumab-based neoadjuvant treatment supports adjuvant ado-trastuzumab emtansine consideration.", sources: ["kadcyla-label-2026", "nci-treatment-2025"], category: "management", limitation: "Oncology referral/selection rather than automatic administration. Residual DCIS alone does not meet this indication; toxicity and eligibility review remain necessary." },
  { slug: "response-localization", statement: "Breast surgery after NST integrates original proven sites and current residual distribution; imaging response does not authorize omission of definitive local surgery.", sources: ["asbrs-bcs-2026"], category: "management", limitation: "Single adequate current source; no modality is universally mandatory and imaging does not prove microscopic clearance." },
  { slug: "diffuse-calcifications", statement: "Diffuse malignant calcifications can preclude breast conservation despite disappearance of a previously enhancing invasive mass.", sources: ["asbrs-bcs-2026"], category: "management", limitation: "Single current source; extent and malignant tissue verification are supplied. Limited multifocal disease is not automatically a mastectomy indication." },
  { slug: "verify-additional-focus", statement: "When an additional imaging focus would change the breast operation, representative tissue verification and imaging-pathology concordance should precede escalation based on that focus.", sources: ["nhs-assessment-2026"], category: "evaluation", limitation: "Single adequate government assessment source; its screening setting is narrower than these surgical applications. No universal routine-MRI recommendation is made." },
  { slug: "specimen-target", statement: "Localization and specimen imaging should confirm removal of the intended nonpalpable lesion; the marker identity must be reconciled with its documented relation to that lesion.", sources: ["asbrs-bcs-2026", "asbrs-margins-2024"], category: "evaluation", limitation: "Two guides from one society are not independent corroboration. Constructed positional data establish the target relation; marker presence or absence alone is insufficient." },
  { slug: "paget-biopsy", statement: "Persistent unilateral nipple skin abnormalities require representative skin tissue evaluation; a parenchymal sample lacking epidermis does not resolve that surface target.", sources: ["nci-paget-2025", "nhs-assessment-2026"], category: "evaluation", limitation: "The exact sample-content application is original reasoning from tissue provenance. No mandatory punch-versus-wedge superiority is asserted." },
  { slug: "paget-extent", statement: "Confirmed Paget disease requires assessment for underlying breast carcinoma, including additional imaging when conventional studies do not establish its extent.", sources: ["nci-paget-2025", "asbrs-bcs-2026"], category: "evaluation", limitation: "MRI is an adjunct for this unresolved extent, not a universal first test or proof of absence of invasion." },
  { slug: "paget-treatment", statement: "Paget treatment must address the involved nipple skin and underlying carcinoma; selected localized disease can undergo an appropriately encompassing breast-conserving resection with radiation.", sources: ["nci-paget-2025", "asbrs-bcs-2026"], category: "management", limitation: "No automatic nipple-sparing pathway. Exact central resection suitability and cosmetic consequences require clinician review." },
  { slug: "ibc-tissue", statement: "Rapid diffuse breast skin changes require tissue diagnosis and extent assessment; a nonrepresentative benign sample cannot settle a persistent suspicious parenchymal target.", sources: ["nci-inflammatory-diagnosis-2025", "nhs-assessment-2026"], category: "evaluation", limitation: "Do not use the skin findings alone as histologic proof. No formal proposed diagnostic score or mandatory symptom-duration cutoff is imported." },
  { slug: "ibc-sequence", statement: "Nonmetastatic inflammatory breast cancer is ordinarily treated with systemic therapy before modified radical mastectomy and postoperative radiation.", sources: ["nci-inflammatory-treatment", "asbrs-bcs-2026", "asbrs-axilla-2026"], category: "management", limitation: "Reassuring response does not erase the original phenotype. No fixed reconstruction timeline is supported here." },
  { slug: "surveillance", statement: "After primary breast cancer treatment, asymptomatic follow-up uses clinical assessment and appropriate breast mammography rather than routine systemic scans or tumor-marker screening.", sources: ["nci-treatment-2025"], category: "management", limitation: "Single adequate government source in this ledger; new symptoms or abnormal examination require a separate diagnostic assessment. No exact first-postradiation interval is authored." },
  { slug: "recurrent-biomarkers", statement: "Recurrent breast cancer may change receptor status, so current tumor tissue can require repeat biomarker assessment for treatment planning.", sources: ["nci-biomarkers-2025"], category: "evaluation", limitation: "Single adequate government source; no exact metastatic regimen is ranked. Germline blood testing does not establish the receptor phenotype of a recurrent tumor." },
  { slug: "receptor-treatment-boundary", statement: "Hormone-receptor-negative breast cancer does not acquire an endocrine-treatment indication from an earlier receptor-positive specimen, and HER2 tumor testing informs HER2-directed treatment.", sources: ["nci-biomarkers-2025"], category: "management", limitation: "Current adequate tumor evaluation governs planning; this does not compare evolving drug regimens or resolve low-expression assay categories." },
  { slug: "extended-neratinib-phase", statement: "Extended adjuvant neratinib after trastuzumab-based therapy is a different treatment phase from response-adapted T-DM1 consideration for residual invasive disease immediately after NST.", sources: ["nci-treatment-2025"], category: "management", limitation: "Targeted phase distinction only; not a recommendation to give neratinib or a current head-to-head regimen ranking." },
];
